import type { Metadata } from 'next'
import { headers } from 'next/headers'
import Link from 'next/link'
import { NavigateButton } from '@/components/NavigateButton'
import { getRecentPosts } from '@/lib/jsonplaceholder'

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

export default async function HomePage() {
  // Reading request headers opts this page into dynamic rendering,
  // matching the previous `getServerSideProps` behavior.
  const userAgent = (await headers()).get('user-agent') ?? ''
  const posts = await getRecentPosts(5)
  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <NavigateButton href="/blog">View All Posts</NavigateButton>
    </div>
  )
}

