const API_URL = 'https://jsonplaceholder.typicode.com'

export type Post = {
  userId: number
  id: number
  title: string
  body: string
}

export type Comment = {
  postId: number
  id: number
  name: string
  email: string
  body: string
}

// Fetched on every request (previously `getServerSideProps`)
export async function getRecentPosts(limit: number): Promise<Post[]> {
  const res = await fetch(`${API_URL}/posts?_limit=${limit}`, {
    cache: 'no-store',
  })
  if (!res.ok) throw new Error(`Failed to fetch recent posts: ${res.status}`)
  return res.json()
}

export async function getPosts(revalidate: number): Promise<Post[]> {
  const res = await fetch(`${API_URL}/posts`, { next: { revalidate } })
  if (!res.ok) throw new Error(`Failed to fetch posts: ${res.status}`)
  return res.json()
}

// Returns `null` when the post doesn't exist so callers can `notFound()`
export async function getPost(
  id: string,
  revalidate: number
): Promise<Post | null> {
  const res = await fetch(`${API_URL}/posts/${id}`, { next: { revalidate } })
  if (res.status === 404) return null
  if (!res.ok) throw new Error(`Failed to fetch post ${id}: ${res.status}`)
  return res.json()
}

export async function getComments(
  postId: string,
  revalidate: number
): Promise<Comment[]> {
  const res = await fetch(`${API_URL}/posts/${postId}/comments`, {
    next: { revalidate },
  })
  if (!res.ok) throw new Error(`Failed to fetch comments: ${res.status}`)
  return res.json()
}

'use client'

import { createContext, useContext, useState } from 'react'
import type { Dispatch, ReactNode, SetStateAction } from 'react'

export type Theme = 'light' | 'dark'

type AppContextValue = {
  theme: Theme
  setTheme: Dispatch<SetStateAction<Theme>>
}

const AppContext = createContext<AppContextValue | null>(null)

export function AppProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<Theme>('light')

  return (
    <AppContext.Provider value={{ theme, setTheme }}>
      {children}
    </AppContext.Provider>
  )
}

export function useAppContext(): AppContextValue {
  const context = useContext(AppContext)
  if (!context) {
    throw new Error('useAppContext must be used within AppProvider')
  }
  return context
}

'use client'

import { useRouter } from 'next/navigation'
import type { ReactNode } from 'react'

export function NavigateButton({
  href,
  children,
}: {
  href: string
  children: ReactNode
}) {
  const router = useRouter()

  return <button onClick={() => router.push(href)}>{children}</button>
}

export function BackButton({ children }: { children: ReactNode }) {
  const router = useRouter()

  return <button onClick={() => router.back()}>{children}</button>
}

import type { Metadata } from 'next'
import { headers } from 'next/headers'
import Link from 'next/link'
import { NavigateButton } from '@/components/NavigateButton'
import { getRecentPosts } from '@/lib/jsonplaceholder'

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

export default async function HomePage() {
  // Reading request headers opts this page into dynamic rendering,
  // matching the previous `getServerSideProps` behavior.
  const userAgent = (await headers()).get('user-agent') ?? ''
  const posts = await getRecentPosts(5)
  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <NavigateButton href="/blog">View All Posts</NavigateButton>
    </div>
  )
}

import type { Metadata } from 'next'
import Link from 'next/link'
import { NavigateButton } from '@/components/NavigateButton'
import { getPosts } from '@/lib/jsonplaceholder'

export const metadata: Metadata = {
  title: 'Blog - My Blog',
  description: 'All blog posts',
}

export default async function BlogIndex() {
  // ISR with 60 second revalidation
  const posts = await getPosts(60)

  return (
    <div>
      <h1>All Blog Posts</h1>

      <div className="posts-grid">
        {posts.map((post) => (
          <div key={post.id} className="post-card">
            <h2>
              <Link href={`/blog/${post.id}`}>{post.title}</Link>
            </h2>
            <p>{post.body.substring(0, 100)}...</p>
            <NavigateButton href={`/blog/${post.id}`}>Read More</NavigateButton>
          </div>
        ))}
      </div>
    </div>
  )
}

import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/NavigateButton'
import { getComments, getPost, getPosts } from '@/lib/jsonplaceholder'

const REVALIDATE_SECONDS = 300 // 5 minutes

// Posts outside of `generateStaticParams` are rendered on demand and cached
// (replaces `fallback: 'blocking'`).
export const dynamicParams = true

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts = await getPosts(REVALIDATE_SECONDS)

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

export async function generateMetadata({
  params,
}: PageProps<'/blog/[id]'>): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id, REVALIDATE_SECONDS)

  if (!post) return {}

  const description = post.body.substring(0, 160)

  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPost({ params }: PageProps<'/blog/[id]'>) {
  const { id } = await params
  const [post, comments] = await Promise.all([
    getPost(id, REVALIDATE_SECONDS),
    getComments(id, REVALIDATE_SECONDS),
  ])

  if (!post) notFound()

  return (
    <article>
      <BackButton>← Back</BackButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

